import 'package:base_project/core/styles/colors.dart';
import 'package:base_project/core/styles/styles.dart';

import 'package:base_project/core/widgets/other/custom_text.dart';
import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';
import '../../model/team_model.dart';

class TeamCardWidget extends StatelessWidget {
  final TeamModel team;
  final bool isFirstPlace;

  const TeamCardWidget({
    super.key,
    required this.team,
    this.isFirstPlace = false,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: BoxDecoration(
        color: ColorManager.textPrimary,
        borderRadius: BorderRadius.circular(16.r),
        border: Border.all(
          color: isFirstPlace ? ColorManager.firstPlaceGlow : ColorManager.cardBorder,
          width: isFirstPlace ? 3.w : 1.w,
        ),
        boxShadow: isFirstPlace
            ? [
          BoxShadow(
            color: ColorManager.firstPlaceGlow.withOpacity(0.6),
            blurRadius: 20,
            spreadRadius: 2,
          ),
        ]
            : null,
      ),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          // Rank Badge
          Align(
            alignment: Alignment.topRight,
            child: Container(
              margin: EdgeInsets.all(8.r),
              padding: EdgeInsets.symmetric(horizontal: 12.w, vertical: 4.h),
              decoration: BoxDecoration(
                color: isFirstPlace ? ColorManager.secondary : Colors.white.withOpacity(0.1),
                borderRadius: BorderRadius.circular(20.r),
              ),
              child: CustomText(
                text: "#${team.id}", // You can adjust rank logic if needed
                textStyle: TextStyles.labelLarge.copyWith(
                  color: isFirstPlace ? Colors.black : Colors.white,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ),
          ),

          // Team Image
          // Container(
          //   width: 64.r,
          //   height: 64.r,
          //   decoration: BoxDecoration(
          //     shape: BoxShape.circle,
          //     border: Border.all(color: Colors.white24, width: 2),
          //     image: DecorationImage(
          //       image: MemoryImage(Uri.parse(team.image).data!.contentAsBytes()), // base64
          //       fit: BoxFit.cover,
          //     ),
          //   ),
          // ),

          SizedBox(height: 12.h),

          // Team Name
          Padding(
            padding: EdgeInsets.symmetric(horizontal: 8.w),
            child: CustomText(
              text: team.name,
              textStyle: TextStyles.teamNameLarge,
              textAlign: TextAlign.center,
              maxLines: 2,
            ),
          ),

          SizedBox(height: 8.h),

          // Score
          CustomText(
            text: team.score.toString(),
            textStyle: TextStyles.scoreHuge.copyWith(
              color: isFirstPlace ? ColorManager.secondary : ColorManager.textPrimary,
            ),
          ),
          SizedBox(height: 8.h),
          SizedBox(height: 12.h),

// Super Powers Row
          if (team.teamSuperPowers.isNotEmpty)
            Wrap(
              alignment: WrapAlignment.center,
              spacing: 8.w,
              children: team.teamSuperPowers.map((power) {
                return Container(
                  width: 34.r,
                  height: 34.r,
                  padding: EdgeInsets.all(6.r),
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.08),
                    shape: BoxShape.circle,
                    border: Border.all(
                      color: Colors.white24,
                    ),
                  ),
                  child: Image.asset(
                    getSuperPowerImage(power.type),
                    fit: BoxFit.contain,
                  ),
                );
              }).toList(),
            ),
        ],
      ),
    );
  }
}

String getSuperPowerImage(String type) {
  switch (type) {
    case "TaxCollector":
      return ''
      ;

    case "DoublePoints":
      return ''
;

    case "Minus":
      return '';

    default:
      return "assets/images/default_power.png";
  }
}

enum SuperPowerType {
  TaxCollector,
  DoublePoints,
  Minus
}